import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";

const matrix = JSON.parse(
  await readFile(
    new URL("../integrations/chatgpt/tool-annotations.json", import.meta.url),
    "utf8",
  ),
);
const target = new URL(
  "../integrations/chatgpt/tool-annotations.md",
  import.meta.url,
);
const keys = [
  "readOnlyHint",
  "destructiveHint",
  "openWorldHint",
  "idempotentHint",
];
const lines = [
  `# MCP annotation justifications — ${matrix.reviewedOn} candidate`,
  "",
  "<!-- Generated by scripts/build-mcp-annotation-docs.mjs; edit tool-annotations.json. -->",
  "",
  `This matrix covers the local candidate’s **${matrix.tools.length} tools**, with`,
  "all optional services connected and both App opt-ins present only in a",
  "synthetic discovery profile. Baseline discovery with both settings absent",
  "retains 75 tools; the two diagnostic and six original-upload tools are hidden.",
  "The reviewed profile",
  "does not execute a handler or activate a real connection.",
  "It describes authorised production behaviour,",
  "including indirect effects; reviewer-account restrictions do not redefine",
  "the general capabilities of the tools.",
  "It proves neither the deployed catalogue nor the catalogue registered in the portal,",
  "nor the values actually reviewed for rejected version 0.3.2.",
  "",
  "Structured source: [tool-annotations.json](tool-annotations.json).",
  "This JSON is an internal evidence matrix, not an official form for addressing an",
  "OpenAI import refusal. The [remediation dossier](../../docs/MCP_ANNOTATION_REMEDIATION.md)",
  "distinguishes local corrections, their tests and outstanding verification.",
  "",
  "## Applied rules",
  "",
  "All four annotations are explicit booleans. OpenAI requires the first three;",
  "idempotence is optional in the reference, but Guteneo also declares",
  "and justifies it for every tool.",
  "",
  "After validated success, the wrapper may persist the activity of an authorised",
  "production connection. This write changes visible connection state;",
  "`readOnlyHint=false` and `idempotentHint=false` therefore describe the complete",
  "contract, even when the business operation only reads. Business keys",
  "still prevent duplication of the operations they protect.",
  "",
  "The destructive marker also covers revocation and irreversible indirect effects.",
  "A network connection to a bounded private account alone does not justify",
  "marking a tool open-world. Descriptions and justifications never replace",
  "scopes, roles, mandates, server guards or host confirmations.",
  "",
  "Official pages differ on whether justifications are required.",
  "The refusal notice supplied on 20 October explicitly requests them:",
  "each value is justified below, without inferring exemption from another page.",
  "",
  ...matrix.policySources.map(
    ({ url }) => `- [Official OpenAI documentation](${url})`,
  ),
  "",
  "## Reproducible verification",
  "",
  "Run `npm run audit:mcp`: discover `tools/list` through the SDK MCP transport",
  "using the explicit `reviewed` synthetic profile,",
  "check exact coverage, boolean values, justifications",
  "and code references. No business handler is called.",
  "This check does not replace semantic handler review or scanning the",
  "deployed server in the portal. `node scripts/build-mcp-annotation-docs.mjs",
  "--check` verifies that this document exactly matches the matrix.",
  "",
  "## Values by tool",
  "",
  "| Tool | readOnlyHint | destructiveHint | openWorldHint | idempotentHint |",
  "| --- | --- | --- | --- | --- |",
  ...matrix.tools.map(
    (tool) =>
      `| \`${tool.name}\` | ${keys.map((key) => `\`${tool.annotations[key]}\``).join(" | ")} |`,
  ),
  "",
  "## Justifications and sources",
  "",
];
for (const tool of matrix.tools) {
  lines.push(`### \`${tool.name}\``, "");
  for (const key of keys) {
    lines.push(
      `- **\`${key}: ${tool.annotations[key]}\`** — ${tool.justification[key]}`,
    );
  }
  lines.push(
    "",
    `Evidence: ${tool.evidence.map(({ path, symbol }) => `[\`${symbol.replaceAll("`", "")}\`](../../${path})`).join(", ")}.`,
    "",
  );
}
const contents = `${lines.join("\n").trimEnd()}\n`;
if (process.argv.slice(2).some((arg) => arg !== "--check"))
  throw new Error(
    "Usage: node scripts/build-mcp-annotation-docs.mjs [--check]",
  );
if (process.argv.includes("--check")) {
  if ((await readFile(target, "utf8")) !== contents)
    throw new Error(
      `Outdated annotation documentation: run node scripts/build-mcp-annotation-docs.mjs (${fileURLToPath(target)}).`,
    );
  console.log(
    `Annotation documentation synchronized: ${matrix.tools.length} tools.`,
  );
} else {
  await writeFile(target, contents);
  console.log(
    `Generated annotation documentation: ${matrix.tools.length} tools.`,
  );
}
